let timer=null,controller=null,lastReport=null;const money=v=>Number.isFinite(v)?new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(v):'—';const pct=v=>Number.isFinite(v)?(v*100).toFixed(2)+'%':'—';const time=v=>v?new Date(v).toLocaleString('en-CA',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'Not yet';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function unmountPilot(){if(timer)clearInterval(timer);timer=null;controller?.abort();controller=null;lastReport=null}
export function mountPilot(){document.querySelector('#main').innerHTML=`<div class="page-heading"><div><p class="eyebrow">LIVE DATA. SIMULATED CAPITAL.</p><h1>A hundred dollars. An honest experiment.</h1><p>Watch the decisions, the costs, and the losses—not just the wins.</p></div><button class="button dark" id="refresh-pilot">Refresh data ↻</button></div><div id="pilot-notice" class="data-banner" role="status">Connecting to the paper ledger and public market feed…</div><div id="pilot-account"></div><div class="dashboard-grid pilot-grid"><section class="panel"><div class="panel-heading"><div><p class="eyebrow">MARKET DATA</p><h2>Live CAD crypto tape</h2><p>Kraken top-of-book · polled every minute while this view is open</p></div><span class="risk-chip">Public data</span></div><div id="pilot-tape" class="pilot-tape">Loading live quotes…</div></section><section class="perspective"><div class="perspective-top"><span class="mini-star">✧</span><span>RISK BEFORE RETURN</span></div><h2>Keep the experiment small.</h2><div class="risk-rules"><div><span>Maximum per position</span><strong>CAD $20</strong></div><div><span>Minimum entry cash reserve</span><strong>CAD $60</strong></div><div><span>Daily loss stop</span><strong>CAD $2</strong></div><div><span>Drawdown stop</span><strong>5%</strong></div><div><span>Leverage & short selling</span><strong>Disabled</strong></div></div><p>Stops are checked at each successful worker run. Gaps and outages can cause larger losses.</p></section></div><div id="pilot-details"></div><section class="panel article page-content"><p class="eyebrow">CANADA FIRST · U.S. SECOND</p><h2>A precise view of our coverage.</h2><div class="coverage-grid"><div><strong>Canadian equities</strong><span class="risk-chip">Feed not connected</span><p>TSX / TSXV need a verified provider and licensing. No invented quotes.</p></div><div><strong>U.S. equities</strong><span class="risk-chip">Feed not connected</span><p>Not in the free pilot. USD conversion and fractional eligibility still need validation.</p></div><div><strong>Options</strong><span class="risk-chip">Execution blocked</span><p>No live chain or expiry engine. Whole-contract premiums and fees must fit the account.</p></div><div><strong>Futures</strong><span class="risk-chip">Execution blocked</span><p>No verified feed or margin schedule. This pilot does not simulate leverage it cannot fund.</p></div></div></section>`;document.querySelector('#refresh-pilot').onclick=refresh;refresh();timer=setInterval(()=>{if(!document.hidden)refresh()},60000)}
async function get(url,signal){const r=await fetch(url,{cache:'no-store',signal});let json;try{json=await r.json()}catch{throw new Error('The API is unavailable on this host. Open the Vercel or local pilot.')}if(!r.ok)throw new Error(json.error||'Data unavailable');return json}
async function refresh(){controller?.abort();controller=new AbortController();const signal=controller.signal;const results=await Promise.allSettled([get('/api/paper',signal),get('/api/market',signal)]);if(signal.aborted||!document.querySelector('#pilot-account'))return;const [paper,market]=results;if(paper.status==='fulfilled'){lastReport=paper.value;renderReport(lastReport)}else{lastReport=null;document.querySelector('#pilot-notice').textContent=paper.reason.message;document.querySelector('#pilot-account').innerHTML=`<div class="market-cards pilot-stats"><article class="market-card"><p>Planned starting capital</p><strong class="stat-value">$100.00 <small>CAD</small></strong><span>No ledger read; current balance unknown</span></article><article class="market-card"><p>Current equity</p><strong class="stat-value">—</strong><span>Cannot verify the account</span></article><article class="market-card"><p>Profit / loss</p><strong class="stat-value">—</strong><span>Never inferred from sample data</span></article><article class="market-card"><p>Worker heartbeat</p><strong class="stat-value">Unknown</strong><span>Open GitHub Actions for status</span></article></div>`;document.querySelector('#pilot-details').innerHTML=`<section class="panel article page-content"><h2>The live feed and the ledger are separate.</h2><p>Quotes can be live even when account synchronization is unavailable. The hourly worker stores its ledger in the private northstar-state branch. Vercel needs a read-only repository token to display it here.</p><p class="source-note"><a href="https://github.com/git-jainamshah/northstar/actions/workflows/paper-pilot.yml" target="_blank" rel="noopener">View worker runs ↗</a></p></section>`}
 if(market.status==='fulfilled'){const data=market.value;document.querySelector('#pilot-tape').innerHTML=data.assets.map(a=>{const stale=Date.now()-a.observedAt>120000;return `<div class="tape-row"><div><strong>${esc(a.id)}</strong><small>${esc(a.source)}</small></div><div><small>BID / ASK</small><strong>${money(a.bid)} / ${money(a.ask)}</strong></div><div><span class="${stale?'risk-chip':'live-chip'}">${stale?'Stale':'Live snapshot'}</span><small>Book update ${time(a.observedAt)}</small><small>Received ${time(a.receivedAt)}</small></div></div>`}).join('')+data.errors.map(e=>`<div class="tape-row"><strong>${esc(e.id)}</strong><span class="error-text">${esc(e.message)}</span></div>`).join('')}else document.querySelector('#pilot-tape').innerHTML=`<p class="error-text">${esc(market.reason.message)}. New paper entries require valid, fresh data.</p>`}
function renderReport(r){const staleWorker=r.workerAgeMs===null||r.workerAgeMs>r.expectedIntervalMs*2;document.querySelector('#pilot-notice').innerHTML=`<span>ⓘ</span><p><strong>${r.halted?'Risk stop active':staleWorker?'Worker heartbeat overdue':'Paper-only experiment'}</strong> · ${esc(r.runtime)}. ${esc(r.scheduling)} ${r.valuationStale?'Some holdings have stale marks; equity is an estimate.':''}</p><a href="https://github.com/git-jainamshah/northstar/actions" target="_blank" rel="noopener">Worker logs ↗</a>`;
 document.querySelector('#pilot-account').innerHTML=`<div class="market-cards pilot-stats"><article class="market-card"><p>Account equity ${r.valuationStale?'· stale estimate':''}</p><strong class="stat-value">${money(r.equity)}</strong><span>Started with CAD $100 · ${time(r.createdAt)}</span></article><article class="market-card"><p>Net profit / loss</p><strong class="stat-value ${r.pnl<0?'loss':'gain'}">${money(r.pnl)}</strong><span>After simulated fees, spreads & slippage</span></article><article class="market-card"><p>Cash available</p><strong class="stat-value">${money(r.cash)}</strong><span>${r.positions.length} open position${r.positions.length===1?'':'s'} · no borrowed money</span></article><article class="market-card"><p>Worker heartbeat</p><strong class="stat-value heartbeat-value">${staleWorker?'Overdue':r.heartbeat?.status==='ok'?'Healthy':'Degraded'}</strong><span>Last run ${time(r.heartbeat?.startedAt)}</span></article></div>`;
 const history=r.history;let chart='<p class="explainer">The equity curve will develop as the worker records observations. No backdated profits.</p>';if(history.length>=2){const low=Math.min(99,...history.map(p=>p.equity)),high=Math.max(101,...history.map(p=>p.equity));const path=history.map((p,i)=>`${i?'L':'M'}${10+i*660/(history.length-1)},${170-(p.equity-low)/(high-low)*150}`).join(' ');chart=`<svg viewBox="0 0 690 195" class="equity-chart" role="img" aria-label="Observed paper equity from ${money(history[0].equity)} to ${money(history.at(-1).equity)}"><path d="M10 20H680 M10 95H680 M10 170H680" stroke="#e4eadf" fill="none"/><path d="${path}" stroke="#64884c" stroke-width="2.5" fill="none"/><text x="10" y="190" fill="#7c8871" font-size="12">${time(history[0].time)}</text><text x="530" y="190" fill="#7c8871" font-size="12">${time(history.at(-1).time)}</text></svg>`}
 document.querySelector('#pilot-details').innerHTML=`<div class="content-grid"><section class="panel article"><p class="eyebrow">OBSERVED, NOT BACKTESTED</p><h2>The paper account’s journey</h2>${chart}<div class="result-legend"><span>Cash benchmark<strong>$100.00</strong></span><span>BTC buy-and-hold estimate<strong>${money(r.benchmark.btc?.lastValue)}</strong></span><span>Max observed drawdown<strong>${pct(r.maxDrawdown)}</strong></span><span>Fees paid<strong>${money(r.fees)}</strong></span></div><p class="source-note">Equity marks include estimated exit costs. BTC benchmark begins with the first valid quote and shares the latest ledger timestamp. Stale marks are not fresh valuations.</p></section><section class="panel article"><p class="eyebrow">EXPLAINABLE DECISIONS</p><h2>What the strategy is doing</h2>${r.halted?`<div class="status-strip">${esc(r.haltReason)}</div>`:''}<div class="decision-list">${r.decisions.slice(0,4).map(d=>`<div><span class="risk-chip">${esc(d.action)}</span><strong>${esc(d.asset)}</strong><small>${time(d.time)}</small><p>${esc(d.reason)}</p></div>`).join('')||'<p>No decisions recorded yet.</p>'}</div></section></div><section class="panel article page-content"><p class="eyebrow">OPEN POSITIONS</p><h2>Where the simulated money is</h2>${r.positions.length?`<div class="trade-table-wrap"><table class="trade-table"><thead><tr><th>Asset</th><th>Quantity</th><th>Cost incl. fees</th><th>Est. exit value</th><th>Unrealized P/L</th></tr></thead><tbody>${r.positions.map(p=>`<tr><td>${esc(p.id)} ${p.stale?'· stale':''}</td><td>${p.qty.toFixed(8)}</td><td>${money(p.cost)}</td><td>${money(p.liquidation)}</td><td>${money(p.unrealizedPnl)}</td></tr>`).join('')}</tbody></table></div>`:'<p>All capital is in cash. The strategy waits for an eligible setup; it does not manufacture trades.</p>'}</section><section class="panel article page-content"><p class="eyebrow">LEARNING, WITH A SEPARATE SCORECARD</p><h2>The shadow model</h2><p>An online logistic model predicts the next completed hour’s direction, scores its previous prediction, then learns. It does not control trades. Its score is uncalibrated and is not a probability of profit.</p><div class="content-grid">${Object.entries(r.models).map(([id,m])=>`<div class="model-card"><h3>${esc(id)}</h3><div class="status-list"><div><span>Training observations</span><strong>${m.samples}</strong></div><div><span>Scored after 100-bar warm-up</span><strong>${m.scored}</strong></div><div><span>Direction accuracy</span><strong>${pct(m.directionalAccuracy)}</strong></div><div><span>Brier score · lower is better</span><strong>${m.brier?.toFixed(4)??'—'}</strong></div><div><span>50/50 baseline Brier</span><strong>${m.baselineBrier?.toFixed(4)??'—'}</strong></div></div></div>`).join('')||'<p>Waiting for valid history.</p>'}</div><p class="source-note">Scores include chronological evaluation on the initial recent history, not just results since launch. No shuffled train/test split, no future candles, no automatic promotion. These metrics do not demonstrate investment profitability.</p></section><section class="panel article page-content"><p class="eyebrow">EVERY SIMULATED FILL</p><h2>The trade journal</h2>${r.trades.length?`<div class="trade-table-wrap"><table class="trade-table"><thead><tr><th>Time</th><th>Asset</th><th>Side</th><th>Quantity</th><th>Fill price</th><th>Fee</th><th>Realized P/L</th></tr></thead><tbody>${[...r.trades].reverse().map(t=>`<tr><td>${time(t.time)}</td><td>${esc(t.asset)}</td><td>${esc(t.side)}</td><td>${t.qty.toFixed(8)}</td><td>${money(t.price)}</td><td>${money(t.fee)}</td><td>${money(t.pnl)}</td></tr>`).join('')}</tbody></table></div>`:'<p>No simulated fills yet. An absence of trades is a valid result.</p>'}<p class="source-note">Assumed fee: 0.40% per leg, plus 0.10% adverse slippage and observed spread. Buys use the ask; sells use the bid. These are conservative experiment settings, not a verified fee quote or a guarantee of execution.</p></section>`}
export function liveConnections(){document.querySelector('#main').innerHTML=`<div class="page-heading"><div><p class="eyebrow">DATA & CONNECTIONS</p><h1>Know what’s running.</h1><p>The data feed, the paper engine, and a real brokerage are separate systems.</p></div></div><div class="content-grid"><section class="panel article"><h2>Kraken public market data</h2><p>BTC/CAD and ETH/CAD top-of-book quotes and completed hourly candles. No login or trading key. Stale, crossed, missing, or incomplete data blocks new paper entries.</p><p class="source-note"><a href="https://docs.kraken.com/api-reference/market-data/get-ohlc-data" target="_blank" rel="noopener">Provider documentation ↗</a></p></section><section class="panel article"><h2>Hourly hosted experiment</h2><p>GitHub Actions runs the paper worker hourly when enabled, with the ledger saved in the private northstar-state branch. Schedules can be delayed or skipped. A stale heartbeat is shown instead of claiming continuous operation.</p><p class="source-note"><a href="https://github.com/git-jainamshah/northstar/actions/workflows/paper-pilot.yml" target="_blank" rel="noopener">Check actual worker status ↗</a></p></section><section class="panel article"><h2>Wealthsimple stays disconnected.</h2><p>No credentials, account access, real orders, margin, or transfers. Any future integration needs a separate read-only connection and explicit authorization.</p></section><section class="panel article"><h2>GitHub → Vercel</h2><p>Main holds the application; pull requests run checks and can receive Vercel previews. The state branch is excluded from deployments. The dashboard requires NORTHSTAR_STATE_TOKEN on the server to read the private paper ledger.</p><p class="source-note"><a href="https://github.com/git-jainamshah/northstar" target="_blank" rel="noopener">Open private repository ↗</a></p></section></div>`}
